/*
 * THE LOADING SCREEN DRAWS THE LOGO (4 Oct 2026, the owner: "i want the
 * loading to be an ember logo ... like the end of the motion ads, but
 * smoother").
 *
 * The mark is drawn in the pen's own order, one smooth front at a steady
 * speed, then un-drawn the same way, and round again - the way a spinner
 * never stops. Every ink pixel carries the moment the front reaches it,
 * worked out once from the owner's artwork and packed into the picture
 * below (16-bit times, the ink, and the bar of the "e" where the strokes
 * cross, which is drawn as one clean band from its first frame).
 *
 * Plain ES5 and a canvas: this runs on the startup screen, BEFORE the app's
 * own code has loaded, on tills as old as Chrome 83 and on the desktop app's
 * local files (the data is inline, so the canvas is never "tainted" and can
 * always be read back). Anything missing -> the plain still logo.
 *
 *   EmberLogo.mount(el)      draws into el (sized by el's CSS); returns stop()
 *   __emberHideBoot()        fades the startup screen out and stops it
 */
(function () {
  var DATA = 'data:image/png;base64,';
  var FILL = 1400, DRAIN = 1400;          // ms: fill, then drain, like a spinner
  var E = 0.012;                           // the soft edge of the front, in time (wide enough for a 3x smaller picture)
  var RGB = [255, 86, 22];                 // the mark's own orange, #FF5616
  var field = null, waiting = [];

  function load(cb) {
    if (field) return cb(field);
    waiting.push(cb);
    if (waiting.length > 1) return;
    var img = new Image();
    img.onload = function () {
      var f = null;
      try {
        var c = document.createElement('canvas');
        c.width = img.width; c.height = img.height;
        var g = c.getContext('2d');
        g.drawImage(img, 0, 0);
        var px = g.getImageData(0, 0, img.width, img.height).data;
        var w = img.width, h = img.height / 2, n = 0, i;
        for (i = 0; i < w * h; i++) if (px[i * 4 + 2] > 0) n++;
        f = { w: w, h: h, n: n, at: new Int32Array(n), tb: new Float32Array(n),
              ta: new Float32Array(n), cov: new Float32Array(n), bf: new Float32Array(n) };
        var k = 0, o = w * h * 4;
        for (i = 0; i < w * h; i++) {
          var p = i * 4;
          if (px[p + 2] === 0) continue;
          f.at[k] = p;
          f.tb[k] = (px[p] * 256 + px[p + 1]) / 65535;
          f.cov[k] = px[p + 2] / 255;
          f.ta[k] = (px[o + p] * 256 + px[o + p + 1]) / 65535;
          f.bf[k] = px[o + p + 2] / 255;
          k++;
        }
      } catch (e) { f = null; }
      field = f || false;
      var q = waiting; waiting = [];
      for (var j = 0; j < q.length; j++) q[j](field);
    };
    img.onerror = function () { field = false; var q = waiting; waiting = []; for (var j = 0; j < q.length; j++) q[j](false); };
    img.src = DATA;
  }

  function reveal(t, head, tail) {
    var a = (head * (1 + 2 * E) - E - t) / E + 0.5;
    a = a < 0 ? 0 : a > 1 ? 1 : a;
    if (tail > -1 && a > 0) {
      var b = (t - (tail * (1 + 2 * E) - E)) / E + 0.5;
      a *= b < 0 ? 0 : b > 1 ? 1 : b;
    }
    return a;
  }

  function still(el) {
    // The plain mark: no canvas, a failed read, or reduced motion.
    var src = (window.__emberBrand || '') + 'brand/logo-mark.png';
    el.innerHTML = '<img alt="" src="' + src + '" style="height:100%;width:auto;display:block;margin:0 auto">';
  }

  function mount(el) {
    var stopped = false, raf = 0;
    var stop = function () { stopped = true; if (raf) (window.cancelAnimationFrame || clearTimeout)(raf); };
    var reduced = false;
    try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* old */ }
    load(function (f) {
      if (stopped) return;
      if (!f) { still(el); return; }
      var cv = document.createElement('canvas');
      cv.width = f.w; cv.height = f.h;
      cv.setAttribute('aria-hidden', 'true');
      cv.style.height = '100%'; cv.style.width = 'auto'; cv.style.display = 'block'; cv.style.margin = '0 auto';
      el.innerHTML = ''; el.appendChild(cv);
      var g = cv.getContext('2d');
      var im = g.createImageData(f.w, f.h), d = im.data, i;
      for (i = 0; i < f.n; i++) { var p = f.at[i]; d[p] = RGB[0]; d[p + 1] = RGB[1]; d[p + 2] = RGB[2]; }
      function paint(head, tail) {
        for (var k = 0; k < f.n; k++) {
          var bf = f.bf[k];
          var a = bf >= 1 ? reveal(f.tb[k], head, tail)
            : bf * reveal(f.tb[k], head, tail) + (1 - bf) * reveal(f.ta[k], head, tail);
          d[f.at[k] + 3] = f.cov[k] * a * 255 + 0.5;
        }
        g.putImageData(im, 0, 0);
      }
      if (reduced) { paint(1, -1); return; }
      // One clock for every frame (a rAF timestamp and Date.now() are not
      // the same clock, and mixing them froze the drawing at its start).
      var clock = function () { return window.performance && performance.now ? performance.now() : Date.now(); };
      var t0 = clock();
      var tick = function () {
        if (stopped) return;
        if (!cv.parentNode) { stopped = true; return; }       // the screen was replaced
        var now = clock();
        var t = (now - t0) % (FILL + DRAIN);
        if (t < FILL) paint(t / FILL, -1); else paint(1, (t - FILL) / DRAIN);
        raf = (window.requestAnimationFrame || function (f2) { return setTimeout(f2, 16); })(tick);
      };
      tick();
    });
    return stop;
  }

  window.EmberLogo = { mount: mount };

  // The startup screen wears the page colour of the look THIS device chose
  // (lib/theme.ts keeps it under 'ember.theme'), so a till in Light does not
  // open on a black screen and then flash to cream.
  function pageColour() {
    var m = null;
    try { m = localStorage.getItem('ember.theme'); } catch (e) { /* private mode */ }
    var light = m === 'light' || m === 'sunlight' || m === 'soft';
    if (m === 'auto') { try { light = window.matchMedia('(prefers-color-scheme: light)').matches; } catch (e) { /* old */ } }
    if (m === 'clock') {
      var dn = { day: '06:00', night: '18:00' };
      try { var v = JSON.parse(localStorage.getItem('ember.theme.clock') || 'null'); if (v && v.day && v.night) dn = v; } catch (e) { /* default */ }
      var mins = function (s) { var p = String(s).split(':'); return (+p[0]) * 60 + (+p[1]); };
      var now = new Date(), t = now.getHours() * 60 + now.getMinutes(), a = mins(dn.day), b = mins(dn.night);
      light = a === b ? true : a < b ? (t >= a && t < b) : (t >= a || t < b);
    }
    if (m === 'sunlight') return '#ffffff';
    if (m === 'soft') return '#e4e6ea';
    if (light) return '#f1ece1';
    if (m === 'midnight') return '#000000';
    if (m === 'dim') return '#202226';
    return '#121415';
  }

  // Every startup screen on the page draws itself.
  function start() {
    var bg = pageColour();
    var ids = ['boot', 'demo-boot'];
    for (var b = 0; b < ids.length; b++) { var s = document.getElementById(ids[b]); if (s) s.style.background = bg; }
    var els = document.querySelectorAll('[data-ember-logo]');
    for (var i = 0; i < els.length; i++) {
      if (els[i].__emberLogo) continue;
      els[i].__emberLogo = mount(els[i]);
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();

  // The app calls this once it is ready to show itself.
  window.__emberHideBoot = function () {
    var ids = ['boot', 'demo-boot'];
    for (var i = 0; i < ids.length; i++) {
      var b = document.getElementById(ids[i]);
      if (!b || b.__leaving) continue;
      b.__leaving = true;
      b.style.transition = 'opacity 220ms ease';
      b.style.opacity = '0';
      b.style.pointerEvents = 'none';
      (function (el) {
        setTimeout(function () {
          var l = el.querySelectorAll('[data-ember-logo]');
          for (var j = 0; j < l.length; j++) if (l[j].__emberLogo) l[j].__emberLogo();
          if (el.parentNode) el.parentNode.removeChild(el);
        }, 240);
      })(b);
    }
  };
})();
